package com.sems.unit.job;
import com.baomidou.mybatisplus.core.conditions.Wrapper;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import com.sems.config.SemsProperties;
import com.sems.infra.*;
import com.sems.job.*;
import com.sems.module.bag.entity.Bag;
import com.sems.module.bag.mapper.BagMapper;
import com.sems.module.order.entity.BagOrder;
import com.sems.module.order.mapper.BagOrderMapper;
import com.sems.module.station.entity.Station;
import com.sems.module.station.mapper.StationMapper;
import com.sems.module.audit.mapper.SysMetricMapper;
import com.sems.push.PushService;
import org.junit.jupiter.api.Test;
import org.springframework.data.redis.core.*;
import java.time.*;
import java.util.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import static org.junit.jupiter.api.Assertions.*;
/** 对账/超时任务验证权威口径、重复守卫和基础设施故障后的下一轮可恢复性。 */
class ReconciliationJobsTest {
 @org.junit.jupiter.api.BeforeAll static void metadata(){com.sems.unit.support.MybatisTestMetadata.init();}
 Bag bag(long id,String code){Bag b=new Bag();b.setId(id);b.setBagCode(code);b.setStationId(1L);b.setStatus("ALLOCATED");return b;}
 BagOrder order(long id,long uid,String code){BagOrder o=new BagOrder();o.setId(id);o.setUserId(uid);o.setBagCode(code);o.setOrderNo("单"+id);o.setStatus("PENDING_SEND");o.setStationId(1L);return o;}
 @Test void currentHolderOnlyAndHistoricHolderIsReset(){BagMapper b=mock(BagMapper.class);BagOrderMapper o=mock(BagOrderMapper.class);CounterService c=mock(CounterService.class);when(b.selectPage(any(Page.class),any(Wrapper.class))).thenReturn(new Page<Bag>().setRecords(List.of(bag(1,"袋1"))));when(o.selectList(any(Wrapper.class))).thenReturn(List.of(order(1,8,"袋1"),order(2,9,"袋1")));when(c.getOpenCount(8L)).thenReturn(1);when(c.getOpenCount(9L)).thenReturn(0);new OpenCountReconcileJob(b,o,c).reconcile();verify(c).setOpenCount(8L,0);verify(c).setOpenCount(9L,1);}
 @Test void noBagsNoOrdersOrMatchingCountsDoNotWrite(){BagMapper b=mock(BagMapper.class);BagOrderMapper o=mock(BagOrderMapper.class);CounterService c=mock(CounterService.class);OpenCountReconcileJob job=new OpenCountReconcileJob(b,o,c);when(b.selectPage(any(Page.class),any(Wrapper.class))).thenReturn(new Page<Bag>());job.reconcile();verifyNoInteractions(o,c);when(b.selectPage(any(Page.class),any(Wrapper.class))).thenReturn(new Page<Bag>().setRecords(List.of(bag(1,"袋1"))));job.reconcile();verifyNoInteractions(c);when(o.selectList(any(Wrapper.class))).thenReturn(List.of(order(1,8,"袋1")));when(c.getOpenCount(8L)).thenReturn(1);job.reconcile();verify(c,never()).setOpenCount(anyLong(),anyInt());when(b.selectPage(any(Page.class),any(Wrapper.class))).thenThrow(new IllegalStateException("查询失败"));assertDoesNotThrow(job::reconcile);}
 @Test void orphanHoldsAreRemovedAndStartupRebuildsStocks() throws Exception {StringRedisTemplate r=mock(StringRedisTemplate.class);BagOrderMapper o=mock(BagOrderMapper.class);StockService stock=mock(StockService.class);Cursor<String> cursor=mock(Cursor.class);when(r.scan(any(ScanOptions.class))).thenReturn(cursor);when(cursor.hasNext()).thenReturn(true,true,false);when(cursor.next()).thenReturn(RedisKeys.stockHold("已建单"),RedisKeys.stockHold("孤儿"));BagOrder existing=order(1,8,"袋");existing.setOrderNo("已建单");when(o.selectList(any(Wrapper.class))).thenReturn(List.of(existing));new StartupRunner(r,o,stock).run(null);verify(r).delete(RedisKeys.stockHold("孤儿"));verify(r,never()).delete(RedisKeys.stockHold("已建单"));verify(stock).initializeAllStations();verify(cursor).close();}
 @Test void startupRedisFailureDoesNotAbortApplication(){StringRedisTemplate r=mock(StringRedisTemplate.class);when(r.scan(any())).thenThrow(new IllegalStateException("扫描失败"));assertDoesNotThrow(()->new StartupRunner(r,mock(BagOrderMapper.class),mock(StockService.class)).run(null));}
 @Test void stableInventoryIsCorrectedAndMarkerAlwaysReleased(){StationMapper stations=mock(StationMapper.class);BagMapper bags=mock(BagMapper.class);StockService stock=mock(StockService.class);StringRedisTemplate r=mock(StringRedisTemplate.class);ValueOperations<String,String> v=mock(ValueOperations.class);SysMetricMapper metrics=mock(SysMetricMapper.class);when(r.opsForValue()).thenReturn(v);Station s=new Station();s.setId(1L);when(stations.selectPage(any(Page.class),any(Wrapper.class))).thenReturn(new Page<Station>().setRecords(List.of(s)));when(v.setIfAbsent(anyString(),eq("1"),any(Duration.class))).thenReturn(true);when(stock.isStationReady(1L)).thenReturn(true);when(bags.selectCount(any(Wrapper.class))).thenReturn(3L);when(v.get(RedisKeys.stockAvailable(1L))).thenReturn("99");new StockReconcileJob(stations,bags,stock,r,metrics).reconcile();verify(v).set(RedisKeys.stockAvailable(1L),"3");verify(metrics).increment(eq(StockReconcileJob.METRIC_STOCK_RECONCILE_DIFF_COUNT),any(LocalDate.class));verify(r).delete(RedisKeys.stockReconcile(1L));}
 @Test void missingSentinelRebuildsAndBusyMarkerSkips(){StationMapper stations=mock(StationMapper.class);BagMapper bags=mock(BagMapper.class);StockService stock=mock(StockService.class);StringRedisTemplate r=mock(StringRedisTemplate.class);ValueOperations<String,String> v=mock(ValueOperations.class);when(r.opsForValue()).thenReturn(v);Station s=new Station();s.setId(1L);when(stations.selectPage(any(Page.class),any(Wrapper.class))).thenReturn(new Page<Station>().setRecords(List.of(s)));StockReconcileJob job=new StockReconcileJob(stations,bags,stock,r,mock(SysMetricMapper.class));job.reconcile();verify(stock,never()).rebuildStationStock(anyLong());verifyNoInteractions(bags);when(v.setIfAbsent(anyString(),eq("1"),any(Duration.class))).thenReturn(true);job.reconcile();verify(stock).rebuildStationStock(1L);verify(r).delete(RedisKeys.stockReconcile(1L));}
 @Test void unstableInventoryDoesNotOverwriteRedis(){StationMapper stations=mock(StationMapper.class);BagMapper bags=mock(BagMapper.class);StockService stock=mock(StockService.class);StringRedisTemplate r=mock(StringRedisTemplate.class);ValueOperations<String,String> v=mock(ValueOperations.class);when(r.opsForValue()).thenReturn(v);Station s=new Station();s.setId(1L);when(stations.selectPage(any(Page.class),any(Wrapper.class))).thenReturn(new Page<Station>().setRecords(List.of(s)));when(v.setIfAbsent(anyString(),eq("1"),any(Duration.class))).thenReturn(true);when(stock.isStationReady(1L)).thenReturn(true);when(bags.selectCount(any(Wrapper.class))).thenReturn(3L,4L);new StockReconcileJob(stations,bags,stock,r,mock(SysMetricMapper.class)).reconcile();verify(v,never()).set(anyString(),anyString());verify(r).delete(RedisKeys.stockReconcile(1L));}
 @Test void timeoutCancellationDoesNotReleaseInventoryOrHoldingQuota(){BagOrderMapper orders=mock(BagOrderMapper.class);BagMapper bags=mock(BagMapper.class);StockService stock=mock(StockService.class);PushService push=mock(PushService.class);BagOrder o=order(1,8,"袋1");when(orders.selectPage(any(Page.class),any(Wrapper.class))).thenReturn(new Page<BagOrder>().setRecords(List.of(o)),new Page<BagOrder>(),new Page<BagOrder>());when(orders.update(isNull(),any(Wrapper.class))).thenReturn(1);new TimeoutOrderJob(orders,bags,stock,push).scan();verify(stock).deleteHold("单1");verify(stock,never()).increaseAvailable(anyLong(),anyInt());verify(push).pushUserOrder(eq(8L),argThat(d->d.toString().contains("CANCELLED")));}
 @Test void timeoutConcurrentCancellationNoDoublePush(){BagOrderMapper o=mock(BagOrderMapper.class);when(o.selectPage(any(Page.class),any(Wrapper.class))).thenReturn(new Page<BagOrder>().setRecords(List.of(order(1,8,"袋"))),new Page<BagOrder>(),new Page<BagOrder>());StockService stock=mock(StockService.class);PushService push=mock(PushService.class);new TimeoutOrderJob(o,mock(BagMapper.class),stock,push).scan();verifyNoInteractions(stock,push);}
}
